begin;
-- A restriction is scoped by its verified subject, organization and explicit
-- purposes. It does not erase historical records or alter mandatory processing.
create table public.dsr_processing_scope_versions_v1(id uuid primary key default extensions.gen_random_uuid(),request_id uuid not null references public.data_subject_requests(id),version integer not null check(version>0),subject_user_id uuid not null references auth.users(id),organization_id uuid not null references public.organizations(id),action text not null check(action in('APPLY','LIFT')),purposes text[]not null check(cardinality(purposes)>0 and purposes<@array['MARKETING','OPTIONAL_AI']::text[]),content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),confirmed_at timestamptz not null default clock_timestamp(),idempotency_key text not null,unique(request_id,version),unique(request_id,idempotency_key));
create table public.dsr_processing_restriction_proposals_v1(id uuid primary key default extensions.gen_random_uuid(),request_id uuid not null references public.data_subject_requests(id),scope_version_id uuid not null references public.dsr_processing_scope_versions_v1(id),subject_user_id uuid not null references auth.users(id),organization_id uuid not null references public.organizations(id),action text not null check(action in('APPLY','LIFT')),purposes text[]not null,reason text not null,legal_reference text not null,content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),proposed_by uuid not null references auth.users(id),proposed_at timestamptz not null default clock_timestamp(),idempotency_key text not null,unique(request_id,idempotency_key));
create table public.dsr_processing_restriction_decisions_v1(proposal_id uuid primary key references public.dsr_processing_restriction_proposals_v1(id),content_hash text not null,decision text not null check(decision in('APPROVE','REJECT')),reason text not null,legal_reference text not null,review_proof_hash text not null,decided_by uuid not null references auth.users(id),decided_at timestamptz not null default clock_timestamp());
create table public.dsr_processing_restriction_applications_v1(id uuid primary key default extensions.gen_random_uuid(),sequence_number bigint generated always as identity unique,proposal_id uuid not null unique references public.dsr_processing_restriction_proposals_v1(id),request_id uuid not null references public.data_subject_requests(id),scope_version_id uuid not null references public.dsr_processing_scope_versions_v1(id),subject_user_id uuid not null references auth.users(id),organization_id uuid not null references public.organizations(id),action text not null check(action in('APPLY','LIFT')),purposes text[]not null,consumer_proof jsonb not null,consumer_proof_hash text not null,document_json text not null,sha256 text not null check(sha256~'^[a-f0-9]{64}$'),applied_by uuid not null references auth.users(id),applied_at timestamptz not null default clock_timestamp());
create table public.dsr_processing_restriction_access_v1(application_id uuid not null references public.dsr_processing_restriction_applications_v1(id),subject_user_id uuid not null references auth.users(id),sha256 text not null,accessed_at timestamptz not null default clock_timestamp(),primary key(application_id,subject_user_id));
create table public.dsr_processing_restriction_receipts_v1(application_id uuid primary key references public.dsr_processing_restriction_applications_v1(id),scope_version_id uuid not null references public.dsr_processing_scope_versions_v1(id),subject_user_id uuid not null references auth.users(id),sha256 text not null,acknowledged_at timestamptz not null default clock_timestamp());
create index dsr_processing_restriction_effective_idx on public.dsr_processing_restriction_applications_v1(organization_id,subject_user_id,sequence_number desc);
do $$declare t text;begin foreach t in array array['dsr_processing_scope_versions_v1','dsr_processing_restriction_proposals_v1','dsr_processing_restriction_decisions_v1','dsr_processing_restriction_applications_v1','dsr_processing_restriction_access_v1','dsr_processing_restriction_receipts_v1']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('create trigger %I before update or delete on public.%I for each row execute function private.prevent_update_delete()',t||'_immutable',t);end loop;end$$;
create function private.dsr_processing_is_restricted_v1(p_organization_id uuid,p_subject_user_id uuid,p_purpose text)returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select coalesce((select action='APPLY'from public.dsr_processing_restriction_applications_v1 where organization_id=p_organization_id and subject_user_id=p_subject_user_id and p_purpose=any(purposes)order by sequence_number desc limit 1),false)$$;
revoke all on function private.dsr_processing_is_restricted_v1(uuid,uuid,text)from public,anon,authenticated,service_role;
create function private.dsr_processing_consumer_evidence_v1(p_purposes text[])returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private as $$declare proof jsonb;begin
 if p_purposes is distinct from array['MARKETING']::text[]then raise exception'DSR_RESTRICTION_SCOPE_NOT_IMPLEMENTED'using errcode='55000';end if;
 if to_regprocedure('private.dsr_restriction_consumer_proof_v1(text)')is null then raise exception'DSR_RESTRICTION_CONSUMER_GUARDS_REQUIRED'using errcode='55000';end if;
 execute'select private.dsr_restriction_consumer_proof_v1($1)'into proof using'MARKETING';
 if proof->>'purpose'is distinct from'MARKETING'or proof->>'ready'is distinct from'true'or proof->>'version'is distinct from'1'or proof->>'guard_count'is distinct from'4'or jsonb_typeof(proof->'guards')is distinct from'array'or jsonb_array_length(proof->'guards')<>4 or(select count(distinct value->>'name')from jsonb_array_elements(proof->'guards'))<>4 or(select array_agg(distinct value->>'type'order by value->>'type')from jsonb_array_elements(proof->'guards'))is distinct from array['MARKETING_BUSINESS_ATTRIBUTION','MARKETING_NOTIFICATION_TRANSPORT','MARKETING_SOURCE_FACT_CAPTURE','MARKETING_TOUCH_REGISTRATION']::text[]or exists(select 1 from jsonb_array_elements(proof->'guards')g where coalesce(g->>'source_hash','')!~'^[a-f0-9]{64}$') then raise exception'DSR_RESTRICTION_CONSUMER_GUARDS_REQUIRED'using errcode='55000';end if;
 return proof;
end$$;
revoke all on function private.dsr_processing_consumer_evidence_v1(text[])from public,anon,authenticated,service_role;
create function public.confirm_my_processing_restriction_scope_v1(p_request_id uuid,p_action text,p_purposes text[],p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare d public.data_subject_requests%rowtype;s public.dsr_processing_scope_versions_v1%rowtype;purposes_value text[];h text;n integer;result jsonb;c uuid:=extensions.gen_random_uuid();begin
 select*into d from public.data_subject_requests where id=p_request_id for update;
 if auth.uid()is null or auth.jwt()->>'aal'is distinct from'aal2'or d.id is null or d.request_type<>'RESTRICTION'or d.status<>'IN_REVIEW'or d.verified_at is null or private.dsr_account_subject_v1(d.id)is distinct from auth.uid()then raise exception'DSR_VERIFIED_SUBJECT_REQUIRED'using errcode='42501';end if;
 if p_action is null or p_action not in('APPLY','LIFT')or p_purposes is null or cardinality(p_purposes)not between 1 and 2 or exists(select 1 from unnest(p_purposes)x where x is null or x not in('MARKETING','OPTIONAL_AI'))or length(coalesce(p_idempotency_key,''))not between 8 and 200 then raise exception'INVALID_DSR_RESTRICTION_SCOPE'using errcode='22023';end if;
 select array_agg(distinct x order by x)into purposes_value from unnest(p_purposes)x;
 h:=private.canonical_request_hash(jsonb_build_object('request',d.id,'organization',d.organization_id,'subject',auth.uid(),'action',p_action,'purposes',purposes_value));
 select*into s from public.dsr_processing_scope_versions_v1 where request_id=d.id and idempotency_key=p_idempotency_key;
 if s.id is not null then if s.content_hash is distinct from h then raise exception'IDEMPOTENCY_KEY_REUSED'using errcode='22023';end if;return jsonb_build_object('outcome','DSR_RESTRICTION_SCOPE_CONFIRMED','scope_version_id',s.id,'version',s.version);end if;
 select coalesce(max(version),0)+1 into n from public.dsr_processing_scope_versions_v1 where request_id=d.id;
 insert into public.dsr_processing_scope_versions_v1(request_id,version,subject_user_id,organization_id,action,purposes,content_hash,idempotency_key)values(d.id,n,auth.uid(),d.organization_id,p_action,purposes_value,h,p_idempotency_key)returning*into s;
 result:=jsonb_build_object('outcome','DSR_RESTRICTION_SCOPE_CONFIRMED','scope_version_id',s.id,'version',s.version,'request_id',d.id,'action',s.action,'purposes',s.purposes);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(d.organization_id,auth.uid(),'USER','privacy.restriction.scope_confirmed','data_subject_request',d.id::text,c,result,repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(d.organization_id,'data_subject_request',d.id::text,'DsrRestrictionScopeConfirmedV1',c,result,'dsr-restriction-scope:'||s.id::text);return result;
end$$;
create function public.propose_dsr_processing_restriction_v1(p_request_id uuid,p_expected_request_row_version integer,p_expected_scope_version_id uuid,p_legal_reference text,p_reason text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare d public.data_subject_requests%rowtype;s public.dsr_processing_scope_versions_v1%rowtype;p public.dsr_processing_restriction_proposals_v1%rowtype;h text;result jsonb;c uuid:=extensions.gen_random_uuid();begin
 if not private.dsr_all_legal_staff_v1()then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';end if;
 select*into d from public.data_subject_requests where id=p_request_id for update;
 if not private.dsr_all_legal_staff_v1()then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';end if;
 select*into s from public.dsr_processing_scope_versions_v1 where request_id=d.id order by version desc limit 1;
 if d.id is null or d.request_type<>'RESTRICTION'or d.status<>'IN_REVIEW'or d.verified_at is null or s.id is null or s.subject_user_id is distinct from private.dsr_account_subject_v1(d.id)then raise exception'DSR_VERIFIED_RESTRICTION_REQUIRED'using errcode='55000';end if;
 if p_expected_request_row_version is null or p_expected_request_row_version<1 or p_expected_request_row_version is distinct from d.row_version or p_expected_scope_version_id is distinct from s.id then raise exception'STALE_DSR_RESTRICTION_SCOPE'using errcode='40001';end if;
 if length(btrim(coalesce(p_legal_reference,'')))not between 8 and 1000 or length(btrim(coalesce(p_reason,'')))not between 10 and 2000 or length(coalesce(p_idempotency_key,''))not between 8 and 200 then raise exception'DSR_DOCUMENTED_RESTRICTION_REQUIRED'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('request',d.id,'scope',s.id,'scope_hash',s.content_hash,'legal_reference',btrim(p_legal_reference),'reason',btrim(p_reason)));
 select*into p from public.dsr_processing_restriction_proposals_v1 where request_id=d.id and idempotency_key=p_idempotency_key;
 if p.id is not null then if p.content_hash is distinct from h or p.proposed_by<>auth.uid()then raise exception'IDEMPOTENCY_KEY_REUSED'using errcode='22023';end if;return jsonb_build_object('outcome','DSR_RESTRICTION_PROPOSED','proposal_id',p.id,'content_hash',p.content_hash);end if;
 insert into public.dsr_processing_restriction_proposals_v1(request_id,scope_version_id,subject_user_id,organization_id,action,purposes,reason,legal_reference,content_hash,proposed_by,idempotency_key)values(d.id,s.id,s.subject_user_id,d.organization_id,s.action,s.purposes,btrim(p_reason),btrim(p_legal_reference),h,auth.uid(),p_idempotency_key)returning*into p;
 result:=jsonb_build_object('outcome','DSR_RESTRICTION_PROPOSED','proposal_id',p.id,'content_hash',h,'request_id',d.id,'scope_version_id',s.id,'action',s.action,'purposes',s.purposes);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(d.organization_id,auth.uid(),'USER','privacy.restriction.proposed','data_subject_request',d.id::text,c,result,repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(d.organization_id,'data_subject_request',d.id::text,'DsrRestrictionProposedV1',c,result,'dsr-restriction-proposal:'||p.id::text);return result;
end$$;
create function public.review_dsr_processing_restriction_v1(p_proposal_id uuid,p_expected_content_hash text,p_approve boolean,p_scope_confirmed boolean,p_legal_reference text,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare p public.dsr_processing_restriction_proposals_v1%rowtype;d public.data_subject_requests%rowtype;r public.dsr_processing_restriction_decisions_v1%rowtype;result jsonb;proof text;c uuid:=extensions.gen_random_uuid();begin
 if not private.dsr_all_legal_staff_v1()then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';end if;
 select*into p from public.dsr_processing_restriction_proposals_v1 where id=p_proposal_id;
 select*into d from public.data_subject_requests where id=p.request_id for update;
 select*into p from public.dsr_processing_restriction_proposals_v1 where id=p_proposal_id for update;
 if not private.dsr_all_legal_staff_v1()or p.proposed_by=auth.uid()then raise exception'DSR_RESTRICTION_INDEPENDENT_REVIEW_REQUIRED'using errcode='42501';end if;
 if p.id is null or d.status<>'IN_REVIEW'or d.verified_at is null or p.scope_version_id is distinct from(select id from public.dsr_processing_scope_versions_v1 where request_id=d.id order by version desc limit 1)then raise exception'STALE_DSR_RESTRICTION_SCOPE'using errcode='40001';end if;
 if p_expected_content_hash is distinct from p.content_hash then raise exception'STALE_DSR_RESTRICTION_PROPOSAL'using errcode='40001';end if;
 if p_approve is null or(p_approve and p_scope_confirmed is distinct from true)or length(btrim(coalesce(p_legal_reference,'')))not between 8 and 1000 or length(btrim(coalesce(p_reason,'')))not between 10 and 2000 then raise exception'DSR_DOCUMENTED_RESTRICTION_REQUIRED'using errcode='22023';end if;
 result:=jsonb_build_object('outcome','DSR_RESTRICTION_REVIEWED','proposal_id',p.id,'content_hash',p.content_hash,'decision',case when p_approve then'APPROVE'else'REJECT'end);
 select*into r from public.dsr_processing_restriction_decisions_v1 where proposal_id=p.id;
 if r.proposal_id is not null then if r.decided_by=auth.uid()and r.decision=result->>'decision'and r.reason=btrim(p_reason)and r.legal_reference=btrim(p_legal_reference)then return result||jsonb_build_object('review_proof_hash',r.review_proof_hash);end if;raise exception'DSR_RESTRICTION_ALREADY_REVIEWED'using errcode='55000';end if;
 proof:=private.canonical_request_hash(result||jsonb_build_object('reviewer',auth.uid(),'legal_reference',btrim(p_legal_reference),'reason',btrim(p_reason)));
 insert into public.dsr_processing_restriction_decisions_v1(proposal_id,content_hash,decision,reason,legal_reference,review_proof_hash,decided_by)values(p.id,p.content_hash,result->>'decision',btrim(p_reason),btrim(p_legal_reference),proof,auth.uid());result:=result||jsonb_build_object('review_proof_hash',proof,'request_id',d.id);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(d.organization_id,auth.uid(),'USER','privacy.restriction.reviewed','data_subject_request',d.id::text,c,result,repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(d.organization_id,'data_subject_request',d.id::text,'DsrRestrictionReviewedV1',c,result,'dsr-restriction-review:'||p.id::text);return result;
end$$;
create function public.apply_dsr_processing_restriction_v1(p_proposal_id uuid,p_expected_content_hash text,p_expected_review_proof_hash text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions set timezone='UTC' as $$
declare p public.dsr_processing_restriction_proposals_v1%rowtype;d public.data_subject_requests%rowtype;r public.dsr_processing_restriction_decisions_v1%rowtype;a public.dsr_processing_restriction_applications_v1%rowtype;scope public.dsr_processing_scope_versions_v1%rowtype;proof jsonb;document jsonb;encoded text;sha text;result jsonb;c uuid:=extensions.gen_random_uuid();now_value timestamptz;begin
 if not private.dsr_all_legal_staff_v1()then raise exception'DSR_LEGAL_STAFF_REQUIRED'using errcode='42501';end if;
 if length(coalesce(p_idempotency_key,''))not between 8 and 200 then raise exception'INVALID_IDEMPOTENCY_KEY'using errcode='22023';end if;
 select*into p from public.dsr_processing_restriction_proposals_v1 where id=p_proposal_id;
 if p.id is null then raise exception'DSR_RESTRICTION_PROPOSAL_NOT_FOUND'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('privacy-processing-restriction:'||p.organization_id::text||':'||p.subject_user_id::text,0));
 select*into d from public.data_subject_requests where id=p.request_id for update;
 select*into p from public.dsr_processing_restriction_proposals_v1 where id=p_proposal_id for update;
 select*into r from public.dsr_processing_restriction_decisions_v1 where proposal_id=p.id;
 select*into scope from public.dsr_processing_scope_versions_v1 where request_id=d.id order by version desc limit 1;
 if not private.dsr_all_legal_staff_v1()or not private.has_platform_role(array['SUPER_ADMIN','COMPLIANCE_MANAGER'],p.proposed_by)or not private.has_platform_role(array['SUPER_ADMIN','COMPLIANCE_MANAGER'],r.decided_by)then raise exception'DSR_RESTRICTION_CURRENT_AUTHORITIES_REQUIRED'using errcode='42501';end if;
 if d.request_type<>'RESTRICTION'or d.verified_at is null or p.scope_version_id is distinct from scope.id or scope.subject_user_id is distinct from p.subject_user_id or scope.organization_id is distinct from p.organization_id or scope.subject_user_id is distinct from private.dsr_account_subject_v1(d.id)then raise exception'STALE_DSR_RESTRICTION_SCOPE'using errcode='40001';end if;
 if p_expected_content_hash is distinct from p.content_hash or p_expected_review_proof_hash is distinct from r.review_proof_hash then raise exception'STALE_DSR_RESTRICTION_PROPOSAL'using errcode='40001';end if;
 if r.proposal_id is null or r.decision<>'APPROVE'or r.content_hash<>p.content_hash or r.decided_by=p.proposed_by then raise exception'DSR_RESTRICTION_APPROVED_REVIEW_REQUIRED'using errcode='55000';end if;
 proof:=private.dsr_processing_consumer_evidence_v1(p.purposes);
 select*into a from public.dsr_processing_restriction_applications_v1 where proposal_id=p.id;
 if a.id is not null then return jsonb_build_object('outcome','DSR_RESTRICTION_APPLIED','application_id',a.id,'sha256',a.sha256,'reference','privacy-restriction:'||a.id::text,'action',a.action,'purposes',a.purposes,'current',private.dsr_restriction_application_current_v1(a.id));end if;
 if d.status<>'IN_REVIEW'then raise exception'DSR_VERIFIED_RESTRICTION_REQUIRED'using errcode='55000';end if;
 now_value:=clock_timestamp();
 document:=jsonb_build_object('format','MATRICIA_PROCESSING_RESTRICTION_PROOF_V1','request_id',d.id,'organization_id',d.organization_id,'scope_version_id',scope.id,'scope_version',scope.version,'action',p.action,'purposes',p.purposes,'applied_at',now_value,'legal_reference',p.legal_reference,'reason',p.reason,'review_legal_reference',r.legal_reference,'review_reason',r.reason,'review_proof_hash',r.review_proof_hash,'consumer_proof',proof,'limitations',jsonb_build_array('ONLY_THIS_SUBJECT_AND_REQUEST_ORGANIZATION','TOUCHES_USE_CAMPAIGN_ORGANIZATION','SOURCE_FACTS_AND_ATTRIBUTION_USE_BUSINESS_SOURCE_ORGANIZATION','NOTIFICATIONS_USE_MESSAGE_ORGANIZATION','EXISTING_BUSINESS_AND_HISTORICAL_RECORDS_PRESERVED','MANDATORY_SECURITY_AND_LEGAL_COMMUNICATIONS_NOT_MARKETING','NO_ERASURE_PERFORMED','OPTIONAL_AI_NOT_IMPLEMENTED'));
 encoded:=document::text;sha:=encode(extensions.digest(convert_to(encoded,'UTF8'),'sha256'),'hex');
 insert into public.dsr_processing_restriction_applications_v1(proposal_id,request_id,scope_version_id,subject_user_id,organization_id,action,purposes,consumer_proof,consumer_proof_hash,document_json,sha256,applied_by,applied_at)values(p.id,d.id,scope.id,p.subject_user_id,p.organization_id,p.action,p.purposes,proof,private.canonical_request_hash(proof),encoded,sha,auth.uid(),now_value)returning*into a;
 result:=jsonb_build_object('outcome','DSR_RESTRICTION_APPLIED','application_id',a.id,'sha256',sha,'reference','privacy-restriction:'||a.id::text,'action',a.action,'purposes',a.purposes,'current',true,'request_id',d.id,'automatically_fulfilled',false);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(d.organization_id,auth.uid(),'USER','privacy.restriction.applied','data_subject_request',d.id::text,c,result,repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(d.organization_id,'data_subject_request',d.id::text,'DsrRestrictionAppliedV1',c,result,'dsr-restriction-application:'||a.id::text);return result;
end$$;
create function private.dsr_restriction_application_current_v1(p_application_id uuid)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare a public.dsr_processing_restriction_applications_v1%rowtype;d public.data_subject_requests%rowtype;proof jsonb;purpose text;begin
 select*into a from public.dsr_processing_restriction_applications_v1 where id=p_application_id;select*into d from public.data_subject_requests where id=a.request_id;
 if a.id is null or d.verified_at is null or d.request_type<>'RESTRICTION'or a.scope_version_id is distinct from(select id from public.dsr_processing_scope_versions_v1 where request_id=d.id order by version desc limit 1)then return false;end if;
 begin proof:=private.dsr_processing_consumer_evidence_v1(a.purposes);exception when sqlstate'55000'then return false;end;
 if private.canonical_request_hash(proof)is distinct from a.consumer_proof_hash or encode(extensions.digest(convert_to(a.document_json,'UTF8'),'sha256'),'hex')is distinct from a.sha256 then return false;end if;
 foreach purpose in array a.purposes loop if private.dsr_processing_is_restricted_v1(a.organization_id,a.subject_user_id,purpose)is distinct from(a.action='APPLY')then return false;end if;end loop;
 return true;
end$$;
revoke all on function private.dsr_restriction_application_current_v1(uuid)from public,anon,authenticated,service_role;
create function public.get_private_dsr_restriction_proof_v1(p_application_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare a public.dsr_processing_restriction_applications_v1%rowtype;subject_value boolean;begin
 select*into a from public.dsr_processing_restriction_applications_v1 where id=p_application_id;
 subject_value:=auth.uid()is not null and auth.jwt()->>'aal'='aal2'and a.subject_user_id=auth.uid()and exists(select 1 from public.data_subject_requests where id=a.request_id and verified_at is not null);
 if a.id is null or not coalesce(subject_value or private.dsr_response_staff_v1(),false)then raise exception'DSR_PRIVATE_RESTRICTION_PROOF_DENIED'using errcode='42501';end if;
 if subject_value then insert into public.dsr_processing_restriction_access_v1(application_id,subject_user_id,sha256)values(a.id,auth.uid(),a.sha256)on conflict do nothing;end if;
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(a.organization_id,auth.uid(),'USER','privacy.restriction.proof_accessed','data_subject_request',a.request_id::text,extensions.gen_random_uuid(),jsonb_build_object('application_id',a.id,'sha256',a.sha256),repeat('0',64));
 return jsonb_build_object('application_id',a.id,'document_json',a.document_json,'sha256',a.sha256,'current',private.dsr_restriction_application_current_v1(a.id));
end$$;
create function public.acknowledge_my_dsr_restriction_v1(p_application_id uuid,p_scope_version_id uuid,p_sha256 text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare a public.dsr_processing_restriction_applications_v1%rowtype;d public.data_subject_requests%rowtype;result jsonb;c uuid:=extensions.gen_random_uuid();begin
 select*into a from public.dsr_processing_restriction_applications_v1 where id=p_application_id;select*into d from public.data_subject_requests where id=a.request_id for update;
 if auth.uid()is null or auth.jwt()->>'aal'is distinct from'aal2'or a.id is null or auth.uid()is distinct from a.subject_user_id or d.verified_at is null then raise exception'DSR_VERIFIED_SUBJECT_REQUIRED'using errcode='42501';end if;
 if p_scope_version_id is distinct from a.scope_version_id or p_sha256 is distinct from a.sha256 or not private.dsr_restriction_application_current_v1(a.id)then raise exception'STALE_DSR_RESTRICTION_PROOF'using errcode='40001';end if;
 if not exists(select 1 from public.dsr_processing_restriction_access_v1 where application_id=a.id and subject_user_id=auth.uid()and sha256=a.sha256)then raise exception'DSR_RESTRICTION_PROOF_ACCESS_REQUIRED'using errcode='55000';end if;
 result:=jsonb_build_object('outcome','DSR_RESTRICTION_ACKNOWLEDGED','request_id',d.id,'application_id',a.id,'sha256',a.sha256);
 if exists(select 1 from public.dsr_processing_restriction_receipts_v1 where application_id=a.id and subject_user_id=auth.uid()and sha256=a.sha256)then return result;end if;
 insert into public.dsr_processing_restriction_receipts_v1(application_id,scope_version_id,subject_user_id,sha256)values(a.id,a.scope_version_id,auth.uid(),a.sha256);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(d.organization_id,auth.uid(),'USER','privacy.restriction.acknowledged','data_subject_request',d.id::text,c,result,repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(d.organization_id,'data_subject_request',d.id::text,'DsrRestrictionAcknowledgedV1',c,result,'dsr-restriction-ack:'||a.id::text);return result;
end$$;
create function private.dsr_processing_restriction_fulfilled_v1(p_request_id uuid,p_reference text)returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$select exists(select 1 from public.dsr_processing_restriction_applications_v1 a join public.dsr_processing_restriction_receipts_v1 receipt on receipt.application_id=a.id and receipt.scope_version_id=a.scope_version_id and receipt.subject_user_id=a.subject_user_id and receipt.sha256=a.sha256 where a.request_id=p_request_id and p_reference='privacy-restriction:'||a.id::text and private.dsr_restriction_application_current_v1(a.id))$$;
revoke all on function private.dsr_processing_restriction_fulfilled_v1(uuid,text)from public,anon,authenticated,service_role;
-- Keep the mature transition checks (including the closed ERASURE gate and
-- complete ALL receipts) and add evidence for actual RESTRICTION effects.
do $$declare definition text;needle text;begin
 select pg_get_functiondef('public.transition_data_subject_request(uuid,integer,text,text,text,uuid)'::regprocedure)into definition;
 needle:='return public.transition_data_subject_request_delivery_internal(';
 if strpos(definition,needle)=0 then raise exception'DSR_RESTRICTION_TRANSITION_PATCH_TARGET_MISSING';end if;
 definition:=replace(definition,needle,'if p_new_status=''FULFILLED''and d.request_type=''RESTRICTION''and not private.dsr_processing_restriction_fulfilled_v1(d.id,reference)then raise exception''PRIVACY_RESTRICTION_EXECUTION_AND_DELIVERY_PROOF_REQUIRED''using errcode=''55000'';end if;'||chr(10)||needle);execute definition;
end$$;
create function public.get_dsr_processing_restriction_console_v1(p_staff boolean default false,p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare items jsonb;total bigint;begin
 if auth.uid()is null or auth.jwt()->>'aal'is distinct from'aal2'or(p_staff and not private.dsr_response_staff_v1())then raise exception'DSR_RESTRICTION_CONSOLE_DENIED'using errcode='42501';end if;
 if p_staff is null or p_page is null or p_page not between 1 and 100000 then raise exception'INVALID_DSR_RESTRICTION_PAGE'using errcode='22023';end if;
 select count(*)into total from public.data_subject_requests d where d.request_type='RESTRICTION'and(p_staff or private.dsr_account_subject_v1(d.id)=auth.uid()or exists(select 1 from public.dsr_processing_scope_versions_v1 s where s.request_id=d.id and s.subject_user_id=auth.uid()));
 select coalesce(jsonb_agg(item order by created_at desc,id),'[]')into items from(select d.created_at,d.id,jsonb_build_object('id',d.id,'row_version',d.row_version,'organization_id',d.organization_id,'organization_name',o.display_name,'status',d.status,'verified',d.verified_at is not null,'due_at',d.due_at,'marketing_restricted',private.dsr_processing_is_restricted_v1(d.organization_id,private.dsr_account_subject_v1(d.id),'MARKETING'),'scope',(select jsonb_build_object('id',s.id,'version',s.version,'action',s.action,'purposes',s.purposes,'content_hash',s.content_hash)from public.dsr_processing_scope_versions_v1 s where s.request_id=d.id order by s.version desc limit 1),'proposal',(select jsonb_build_object('id',p.id,'scope_version_id',p.scope_version_id,'action',p.action,'purposes',p.purposes,'reason',p.reason,'legal_reference',p.legal_reference,'content_hash',p.content_hash,'proposed_by',case when p_staff then p.proposed_by end,'decision',r.decision,'review_proof_hash',r.review_proof_hash,'review_reason',r.reason,'review_legal_reference',r.legal_reference,'can_review',p_staff and private.dsr_all_legal_staff_v1()and p.proposed_by<>auth.uid()and r.proposal_id is null,'can_apply',coalesce(p_staff and private.dsr_all_legal_staff_v1()and r.decision='APPROVE'and not exists(select 1 from public.dsr_processing_restriction_applications_v1 where proposal_id=p.id),false))from public.dsr_processing_restriction_proposals_v1 p left join public.dsr_processing_restriction_decisions_v1 r on r.proposal_id=p.id where p.request_id=d.id order by p.proposed_at desc,p.id desc limit 1),'application',(select jsonb_build_object('id',a.id,'scope_version_id',a.scope_version_id,'action',a.action,'purposes',a.purposes,'sha256',a.sha256,'applied_at',a.applied_at,'current',private.dsr_restriction_application_current_v1(a.id),'acknowledged',exists(select 1 from public.dsr_processing_restriction_receipts_v1 where application_id=a.id and sha256=a.sha256),'reference','privacy-restriction:'||a.id::text)from public.dsr_processing_restriction_applications_v1 a where a.request_id=d.id order by a.sequence_number desc limit 1))item from(select*from public.data_subject_requests d where d.request_type='RESTRICTION'and(p_staff or private.dsr_account_subject_v1(d.id)=auth.uid()or exists(select 1 from public.dsr_processing_scope_versions_v1 s where s.request_id=d.id and s.subject_user_id=auth.uid()))order by d.created_at desc,d.id limit 25 offset((p_page-1)*25))d join public.organizations o on o.id=d.organization_id)selected;
 return jsonb_build_object('actor_id',auth.uid(),'can_manage',p_staff and private.dsr_all_legal_staff_v1(),'items',items,'page',p_page,'has_next',p_page::bigint*25<total,'total',total);
end$$;
revoke all on function public.confirm_my_processing_restriction_scope_v1(uuid,text,text[],text),public.propose_dsr_processing_restriction_v1(uuid,integer,uuid,text,text,text),public.review_dsr_processing_restriction_v1(uuid,text,boolean,boolean,text,text),public.apply_dsr_processing_restriction_v1(uuid,text,text,text),public.get_private_dsr_restriction_proof_v1(uuid),public.acknowledge_my_dsr_restriction_v1(uuid,uuid,text),public.get_dsr_processing_restriction_console_v1(boolean,integer)from public,anon,authenticated,service_role;
grant execute on function public.confirm_my_processing_restriction_scope_v1(uuid,text,text[],text),public.propose_dsr_processing_restriction_v1(uuid,integer,uuid,text,text,text),public.review_dsr_processing_restriction_v1(uuid,text,boolean,boolean,text,text),public.apply_dsr_processing_restriction_v1(uuid,text,text,text),public.get_private_dsr_restriction_proof_v1(uuid),public.acknowledge_my_dsr_restriction_v1(uuid,uuid,text),public.get_dsr_processing_restriction_console_v1(boolean,integer)to authenticated;
notify pgrst,'reload schema';
commit;
